import test from "node:test";
import assert from "node:assert/strict";
import { Queue } from "./attempt.js";

const todo = Queue.prototype.enqueue.toString().includes("TODO");
const skip = todo && "unsolved — edit attempt.js (delete the TODO lines) to activate these tests";

test("first in, first out", { skip }, () => {
  const q = new Queue();
  q.enqueue(1);
  q.enqueue(2);
  q.enqueue(3);
  assert.equal(q.dequeue(), 1); // the oldest leaves first
  assert.equal(q.dequeue(), 2);
  assert.equal(q.dequeue(), 3);
});

test("peek returns the front without removing it", { skip }, () => {
  const q = new Queue();
  q.enqueue("a");
  q.enqueue("b");
  assert.equal(q.peek(), "a");
  assert.equal(q.dequeue(), "a"); // peek did not consume it
  assert.equal(q.peek(), "b");
});

test("enqueue and dequeue interleaved keep the order", { skip }, () => {
  const q = new Queue();
  q.enqueue("a");
  q.enqueue("b");
  assert.equal(q.dequeue(), "a");
  q.enqueue("c"); // arrives while older values are still waiting
  assert.equal(q.dequeue(), "b"); // NOT "c"
  assert.equal(q.dequeue(), "c");
  assert.equal(q.isEmpty(), true);
});

test("empty queue returns undefined instead of throwing", { skip }, () => {
  const q = new Queue();
  assert.equal(q.isEmpty(), true);
  assert.equal(q.dequeue(), undefined);
  assert.equal(q.peek(), undefined);
});

test("many values keep their order (amortized O(1))", { skip }, () => {
  const q = new Queue();
  const out = [];
  for (let i = 0; i < 200; i++) q.enqueue(i);
  for (let i = 0; i < 100; i++) out.push(q.dequeue());
  for (let i = 200; i < 250; i++) q.enqueue(i);
  while (!q.isEmpty()) out.push(q.dequeue());
  assert.deepEqual(out, Array.from({ length: 250 }, (_, i) => i));
});

/**
 * Queue with Two Stacks — FIFO built from two LIFOs.
 *
 * The trick: popping one stack into another reverses the order, so the
 * *bottom* of the inbox (the oldest value) becomes the *top* of the
 * outbox (the cheap end). We only pay for that transfer when the
 * outbox runs dry, which makes every operation amortized O(1).
 *
 * Invariant: the outbox holds older values than the inbox, in
 * front-first order; the inbox holds newer values in arrival order.
 */
export class Queue {
  constructor() {
    /** @type {*[]} newest values, in arrival order (top = newest) */
    this.inbox = [];
    /** @type {*[]} older values, reversed (top = oldest = the front) */
    this.outbox = [];
  }

  /**
   * Add a value at the back of the queue. Always O(1).
   * @param {*} value
   * @returns {void}
   */
  enqueue(value) {
    this.inbox.push(value);
  }

  /**
   * Internal helper: if the outbox is empty, pour the whole inbox into
   * it, reversing the order on the way. Only ever called when the
   * outbox is empty, so no value can jump the queue.
   * @returns {void}
   */
  refill() {
    if (this.outbox.length === 0) {
      while (this.inbox.length > 0) {
        this.outbox.push(this.inbox.pop());
      }
    }
  }

  /**
   * Remove and return the value at the front of the queue.
   * @returns {*} the removed value, or undefined if the queue is empty
   */
  dequeue() {
    this.refill();
    return this.outbox.pop(); // undefined when both stacks are empty
  }

  /**
   * Return the front value without removing it.
   * @returns {*} the front value, or undefined if the queue is empty
   */
  peek() {
    this.refill();
    return this.outbox[this.outbox.length - 1]; // undefined when empty
  }

  /**
   * Is the queue empty? Only when BOTH stacks are.
   * @returns {boolean}
   */
  isEmpty() {
    return this.inbox.length === 0 && this.outbox.length === 0;
  }
}

